{"file_text":"import { SecretClient, KeyVaultSecret } from '@azure/keyvault-secrets';
import { DefaultAzureCredential } from '@azure/identity';

export interface SecretInfo {
  name: string;
  value: string;
  version?: string;
  expiresOn?: Date;
  enabled?: boolean;
}

export class SecretProvider {
  private client: SecretClient;

  constructor(vaultUrl: string) {
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
  }

  /**
   * Retrieves a secret by name with graceful handling for missing secrets
   * @param secretName The name of the secret
   * @param defaultValue Value to return if secret doesn't exist
   * @param version Optional specific version to retrieve
   * @returns SecretInfo or default value
   */
  async getSecret(
    secretName: string,
    defaultValue?: string,
    version?: string
  ): Promise<SecretInfo | null> {
    try {
      const secret = version
        ? await this.client.getSecret(secretName, { version })
        : await this.client.getSecret(secretName);

      return this.mapToSecretInfo(secret);
    } catch (error: any) {
      // Handle 404 - secret not found
      if (error.statusCode === 404) {
        console.warn(
          `Secret '${secretName}' not found in Key Vault. Using default value.`
        );
        return defaultValue
          ? {
              name: secretName,
              value: defaultValue,
              version: undefined,
              expiresOn: undefined,
              enabled: true,
            }
          : null;
      }

      // Re-throw other errors (auth, network, etc.)
      console.error(`Error retrieving secret '${secretName}':`, error.message);
      throw error;
    }
  }

  /**
   * Retrieves a specific version of a secret
   * @param secretName The name of the secret
   * @param version The version ID to retrieve
   * @returns SecretInfo for the specific version
   */
  async getSecretVersion(
    secretName: string,
    version: string
  ): Promise<SecretInfo | null> {
    return this.getSecret(secretName, undefined, version);
  }

  /**
   * Checks if a secret is expiring within the specified warning window
   * @param secretName The name of the secret
   * @param warningDays Number of days before expiry to warn
   * @returns Object with expiry information
   */
  async checkSecretExpiry(
    secretName: string,
    warningDays: number = 7
  ): Promise<{
    isExpiring: boolean;
    expiresOn?: Date;
    daysUntilExpiry?: number;
  }> {
    const secret = await this.getSecret(secretName);

    if (!secret || !secret.expiresOn) {
      return { isExpiring: false };
    }

    const now = new Date();
    const expiryDate = secret.expiresOn;
    const daysUntilExpiry = Math.ceil(
      (expiryDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)
    );

    return {
      isExpiring: daysUntilExpiry <= warningDays && daysUntilExpiry > 0,
      expiresOn: expiryDate,
      daysUntilExpiry,
    };
  }

  /**
   * Lists all versions of a secret
   * @param secretName The name of the secret
   * @returns Array of version IDs
   */
  async listSecretVersions(secretName: string): Promise<string[]> {
    const versions: string[] = [];

    try {
      for await (const properties of this.client.listPropertiesOfSecretVersions(
        secretName
      )) {
        if (properties.version) {
          versions.push(properties.version);
        }
      }
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`Secret '${secretName}' not found.`);
        return [];
      }
      throw error;
    }

    return versions;
  }

  private mapToSecretInfo(secret: KeyVaultSecret): SecretInfo {
    return {
      name: secret.name,
      value: secret.value || '',
      version: secret.properties.version,
      expiresOn: secret.properties.expiresOn,
      enabled: secret.properties.enabled,
    };
  }
}
