{"file_text":"import { SecretProvider, SecretInfo } from './SecretProvider';

interface CacheEntry {
  secretInfo: SecretInfo;
  cachedAt: Date;
}

export class CachingSecretProvider {
  private cache: Map<string, CacheEntry> = new Map();
  private expiryWarningDays: number;

  constructor(
    private secretProvider: SecretProvider,
    expiryWarningDays: number = 7
  ) {
    this.expiryWarningDays = expiryWarningDays;
  }

  /**
   * Bulk-loads a predefined set of required config keys at startup
   * @param secretNames Array of secret names to preload
   * @param defaultValues Optional map of default values for secrets
   * @returns Map of loaded secrets
   */
  async bulkLoad(
    secretNames: string[],
    defaultValues?: Map<string, string>
  ): Promise<Map<string, SecretInfo>> {
    console.log(`Bulk loading ${secretNames.length} secrets...`);
    const results = new Map<string, SecretInfo>();

    const promises = secretNames.map(async (name) => {
      const defaultValue = defaultValues?.get(name);
      const secret = await this.secretProvider.getSecret(name, defaultValue);

      if (secret) {
        this.cache.set(name, {
          secretInfo: secret,
          cachedAt: new Date(),
        });
        results.set(name, secret);
      }
    });

    await Promise.all(promises);
    console.log(`Successfully loaded ${results.size} secrets into cache.`);

    return results;
  }

  /**
   * Retrieves a secret from cache or fetches it if not cached
   * @param secretName The name of the secret
   * @param defaultValue Optional default value if secret doesn't exist
   * @returns SecretInfo from cache or freshly fetched
   */
  async getSecret(
    secretName: string,
    defaultValue?: string
  ): Promise<SecretInfo | null> {
    const cached = this.cache.get(secretName);

    if (cached) {
      console.log(`Cache hit for secret '${secretName}'`);
      return cached.secretInfo;
    }

    console.log(`Cache miss for secret '${secretName}', fetching...`);
    const secret = await this.secretProvider.getSecret(
      secretName,
      defaultValue
    );

    if (secret) {
      this.cache.set(secretName, {
        secretInfo: secret,
        cachedAt: new Date(),
      });
    }

    return secret;
  }

  /**
   * Refreshes a specific secret by fetching it again from Key Vault
   * @param secretName The name of the secret to refresh
   * @param defaultValue Optional default value
   * @returns Updated SecretInfo
   */
  async refreshSecret(
    secretName: string,
    defaultValue?: string
  ): Promise<SecretInfo | null> {
    console.log(`Refreshing secret '${secretName}' from Key Vault...`);
    const secret = await this.secretProvider.getSecret(
      secretName,
      defaultValue
    );

    if (secret) {
      this.cache.set(secretName, {
        secretInfo: secret,
        cachedAt: new Date(),
      });
      console.log(`Secret '${secretName}' refreshed successfully.`);
    }

    return secret;
  }

  /**
   * Automatically re-fetches secrets that are expiring within the warning window
   * @returns Array of refreshed secret names
   */
  async refreshExpiringSecrets(): Promise<string[]> {
    console.log('Checking for expiring secrets...');
    const refreshed: string[] = [];

    const checkPromises = Array.from(this.cache.keys()).map(async (name) => {
      const expiryInfo = await this.secretProvider.checkSecretExpiry(
        name,
        this.expiryWarningDays
      );

      if (expiryInfo.isExpiring) {
        console.log(
          `Secret '${name}' is expiring in ${expiryInfo.daysUntilExpiry} days. Refreshing...`
        );
        await this.refreshSecret(name);
        refreshed.push(name);
      }
    });

    await Promise.all(checkPromises);

    if (refreshed.length > 0) {
      console.log(`Refreshed ${refreshed.length} expiring secret(s).`);
    } else {
      console.log('No secrets are expiring within the warning window.');
    }

    return refreshed;
  }

  /**
   * Checks all cached secrets for expiry warnings
   * @returns Array of secrets with their expiry information
   */
  async checkAllSecretsExpiry(): Promise<
    Array<{
      name: string;
      isExpiring: boolean;
      expiresOn?: Date;
      daysUntilExpiry?: number;
    }>
  > {
    const results: Array<{
      name: string;
      isExpiring: boolean;
      expiresOn?: Date;
      daysUntilExpiry?: number;
    }> = [];

    const checkPromises = Array.from(this.cache.keys()).map(async (name) => {
      const expiryInfo = await this.secretProvider.checkSecretExpiry(
        name,
        this.expiryWarningDays
      );
      results.push({ name, ...expiryInfo });
    });

    await Promise.all(checkPromises);
    return results;
  }

  /**
   * Clears the entire cache
   */
  clearCache(): void {
    this.cache.clear();
    console.log('Cache cleared.');
  }

  /**
   * Removes a specific secret from cache
   * @param secretName The name of the secret to remove
   */
  removeCachedSecret(secretName: string): void {
    this.cache.delete(secretName);
    console.log(`Secret '${secretName}' removed from cache.`);
  }

  /**
   * Gets cache statistics
   * @returns Object with cache stats
   */
  getCacheStats(): {
    size: number;
    secrets: Array<{ name: string; cachedAt: Date }>;
  } {
    const secrets = Array.from(this.cache.entries()).map(([name, entry]) => ({
      name,
      cachedAt: entry.cachedAt,
    }));

    return {
      size: this.cache.size,
      secrets,
    };
  }
}
