{"file_text":"import { SecretClient, SetSecretOptions } from '@azure/keyvault-secrets';
import { DefaultAzureCredential } from '@azure/identity';

export interface RotationOptions {
  expiresOn?: Date;
  contentType?: string;
  tags?: Record<string, string>;
  enabled?: boolean;
}

export class SecretRotationHelper {
  private client: SecretClient;

  constructor(vaultUrl: string) {
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
  }

  /**
   * Rotates a secret by creating a new version with updated value and expiry
   * @param secretName The name of the secret
   * @param newValue The new secret value
   * @param options Rotation options including expiry date
   * @returns The version ID of the newly created secret
   */
  async rotateSecret(
    secretName: string,
    newValue: string,
    options?: RotationOptions
  ): Promise<string> {
    console.log(`Rotating secret '${secretName}'...`);

    const setOptions: SetSecretOptions = {
      expiresOn: options?.expiresOn,
      contentType: options?.contentType,
      tags: options?.tags,
      enabled: options?.enabled ?? true,
    };

    const secret = await this.client.setSecret(
      secretName,
      newValue,
      setOptions
    );

    console.log(
      `Secret '${secretName}' rotated successfully. New version: ${secret.properties.version}`
    );

    return secret.properties.version || '';
  }

  /**
   * Deletes a specific version of a secret (begins long-running operation)
   * @param secretName The name of the secret
   * @returns DeletedSecret with recovery info
   */
  async deleteSecret(secretName: string): Promise<{
    name: string;
    recoveryId?: string;
    deletedOn?: Date;
    scheduledPurgeDate?: Date;
  }> {
    console.log(`Deleting secret '${secretName}'...`);

    const poller = await this.client.beginDeleteSecret(secretName);
    const deletedSecret = await poller.pollUntilDone();

    console.log(
      `Secret '${secretName}' deleted. Scheduled purge date: ${deletedSecret.properties.scheduledPurgeDate}`
    );

    return {
      name: deletedSecret.name,
      recoveryId: deletedSecret.properties.recoveryId,
      deletedOn: deletedSecret.properties.deletedOn,
      scheduledPurgeDate: deletedSecret.properties.scheduledPurgeDate,
    };
  }

  /**
   * Purges a deleted secret permanently (cannot be recovered)
   * IMPORTANT: Secret must be deleted first and delete operation must complete
   * @param secretName The name of the deleted secret
   */
  async purgeDeletedSecret(secretName: string): Promise<void> {
    console.log(`Purging deleted secret '${secretName}'...`);

    try {
      await this.client.purgeDeletedSecret(secretName);
      console.log(`Secret '${secretName}' purged successfully.`);
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(
          `Secret '${secretName}' not found in deleted secrets. May already be purged.`
        );
      } else {
        throw error;
      }
    }
  }

  /**
   * Safely rotates a secret and cleans up the old version
   * Creates new version, deletes and purges the secret to allow full name reuse
   * @param secretName The name of the secret
   * @param newValue The new secret value
   * @param options Rotation options
   * @returns The version ID of the new secret
   */
  async rotateAndCleanup(
    secretName: string,
    newValue: string,
    options?: RotationOptions
  ): Promise<string> {
    console.log(
      `Starting safe rotation with cleanup for secret '${secretName}'...`
    );

    // Step 1: Create new version
    const newVersion = await this.rotateSecret(secretName, newValue, options);

    // Step 2: Delete the secret (starts long-running operation)
    console.log('Waiting for delete operation to complete...');
    const deleteResult = await this.deleteSecret(secretName);

    // Step 3: Purge the deleted secret
    // Wait a moment to ensure delete operation is fully propagated
    await this.sleep(2000);
    await this.purgeDeletedSecret(secretName);

    console.log(
      `Secret '${secretName}' rotated and cleaned up successfully. New version: ${newVersion}`
    );

    return newVersion;
  }

  /**
   * Lists all versions of a secret
   * @param secretName The name of the secret
   * @returns Array of version information
   */
  async listSecretVersions(
    secretName: string
  ): Promise<
    Array<{
      version: string;
      enabled: boolean;
      createdOn?: Date;
      updatedOn?: Date;
    }>
  > {
    const versions: Array<{
      version: string;
      enabled: boolean;
      createdOn?: Date;
      updatedOn?: Date;
    }> = [];

    try {
      for await (const properties of this.client.listPropertiesOfSecretVersions(
        secretName
      )) {
        versions.push({
          version: properties.version || '',
          enabled: properties.enabled || false,
          createdOn: properties.createdOn,
          updatedOn: properties.updatedOn,
        });
      }
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`Secret '${secretName}' not found.`);
        return [];
      }
      throw error;
    }

    return versions;
  }

  /**
   * Disables a specific version of a secret
   * @param secretName The name of the secret
   * @param version The version to disable
   */
  async disableSecretVersion(
    secretName: string,
    version: string
  ): Promise<void> {
    console.log(`Disabling version ${version} of secret '${secretName}'...`);

    await this.client.updateSecretProperties(secretName, version, {
      enabled: false,
    });

    console.log(`Version ${version} disabled successfully.`);
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
