import { CachingSecretProvider } from './CachingSecretProvider';
import { SecretRotationHelper } from './SecretRotationHelper';

export class ConfigurationModule {
  private vaultUrl: string;
  public secretProvider: SecretProvider;
  public cachingProvider: CachingSecretProvider;
  public rotationHelper: SecretRotationHelper;

  constructor(expiryWarningDays: number = 7) {
    // Get vault URL from environment variable
    this.vaultUrl = process.env.AZURE_KEY_VAULT_URL || '';

    if (!this.vaultUrl) {
      throw new Error(
        'AZURE_KEY_VAULT_URL environment variable is not set. ' +
          'Please set it to your Key Vault URL (e.g., https://my-vault.vault.azure.net/)'
      );
    }

    console.log(`Initializing configuration module with vault: ${this.vaultUrl}`);
    console.log('Using DefaultAzureCredential for managed identity authentication.');

    // Initialize providers with managed identity authentication
    this.secretProvider = new SecretProvider(this.vaultUrl);
    this.cachingProvider = new CachingSecretProvider(
      this.secretProvider,
      expiryWarningDays
    );
    this.rotationHelper = new SecretRotationHelper(this.vaultUrl);
  }

  /**
   * Gets the vault URL being used
   */
  getVaultUrl(): string {
    return this.vaultUrl;
  }

  /**
   * Initializes the configuration by bulk-loading required secrets
   * @param requiredSecrets Array of secret names to preload
   * @param defaultValues Optional map of default values
   */
  async initialize(
    requiredSecrets: string[],
    defaultValues?: Map<string, string>
  ): Promise<void> {
    console.log('Initializing configuration module...');
    await this.cachingProvider.bulkLoad(requiredSecrets, defaultValues);
    console.log('Configuration module initialized successfully.');
  }

  /**
   * Gets a configuration value from cache
   * @param key The configuration key (secret name)
   * @param defaultValue Optional default value
   */
  async getConfig(key: string, defaultValue?: string): Promise<string> {
    const secret = await this.cachingProvider.getSecret(key, defaultValue);
    return secret?.value || defaultValue || '';
  }

  /**
   * Refreshes a configuration value
   * @param key The configuration key to refresh
   */
  async refreshConfig(key: string): Promise<void> {
    await this.cachingProvider.refreshSecret(key);
  }

  /**
   * Checks and refreshes expiring secrets
   */
  async maintainSecrets(): Promise<void> {
    await this.cachingProvider.refreshExpiringSecrets();
  }
}
