    console.log('-'.repeat(80));

    const requiredSecrets = [
      'database-connection-string',
      'api-key',
      'encryption-key',
    ];

    const defaultValues = new Map<string, string>([
      ['database-connection-string', 'Server=localhost;Database=default'],
      ['api-key', 'default-api-key-12345'],
      ['encryption-key', 'default-encryption-key-abc'],
