    for (const secretName of requiredSecrets) {
      const value = await config.getConfig(secretName);
      console.log(`${secretName}: ${maskValue(value)}`);
    }
    console.log();

    // Step 4: Refresh a single secret
    console.log('STEP 4: Refresh Single Secret');
    console.log('-'.repeat(80));

    await config.refreshConfig('api-key');
    const refreshedValue = await config.getConfig('api-key');
    console.log(`Refreshed api-key: ${maskValue(refreshedValue)}`);
    console.log();

    // Step 5: Check expiry warnings
    console.log('STEP 5: Check Expiry Warnings');
    console.log('-'.repeat(80));

    const expiryInfo = await config.cachingProvider.checkAllSecretsExpiry();

    for (const info of expiryInfo) {
      if (info.isExpiring) {
        console.log(
          `⚠️  WARNING: Secret '${info.name}' is expiring in ${info.daysUntilExpiry} days!`
        );
        console.log(`   Expires on: ${info.expiresOn}`);
      } else if (info.expiresOn) {
        console.log(
          `✓ Secret '${info.name}' expires on ${info.expiresOn} (${info.daysUntilExpiry} days)`
        );
      } else {
        console.log(`✓ Secret '${info.name}' has no expiration date set.`);
      }
    }
    console.log();

    // Step 6: Demonstrate secret rotation
