    // Create initial secret
    console.log(`Creating initial secret '${testSecretName}'...`);
    const expiryDate = new Date();
    expiryDate.setDate(expiryDate.getDate() + 30); // Expires in 30 days

    const initialVersion = await config.rotationHelper.rotateSecret(
      testSecretName,
      'initial-secret-value-v1',
      {
        expiresOn: expiryDate,
        tags: { rotated: 'false', version: '1' },
      }
    );
    console.log(`Initial version created: ${initialVersion}`);
    console.log();

