      testSecretName,
      'rotated-secret-value-v2',
      {
        expiresOn: newExpiryDate,
        tags: { rotated: 'true', version: '2' },
      }
    );
    console.log(`New version created: ${newVersion}`);
    console.log();

    // List all versions
    console.log('Listing all versions of the secret...');
    const versions = await config.rotationHelper.listSecretVersions(
      testSecretName
    );
    console.log(`Found ${versions.length} version(s):`);
    versions.forEach((v, idx) => {
      console.log(
        `  ${idx + 1}. Version ${v.version} - Enabled: ${v.enabled}, Created: ${v.createdOn}`
      );
    });
    console.log();

    // Step 7: Demonstrate delete and purge cleanup
    console.log('STEP 7: Delete and Purge Cleanup Demo');
    console.log('-'.repeat(80));

    console.log('Demonstrating safe delete and purge operation...');
    console.log('NOTE: This will delete and purge the test secret permanently.');

    // Delete the secret (long-running operation)
    const deleteResult = await config.rotationHelper.deleteSecret(
      testSecretName
    );
    console.log(`Secret deleted. Recovery ID: ${deleteResult.recoveryId}`);
    console.log(`Scheduled purge date: ${deleteResult.scheduledPurgeDate}`);
    console.log();

    // Wait a moment for delete to propagate
    console.log('Waiting for delete operation to propagate...');
    await sleep(3000);
    console.log();

    // Purge the deleted secret
    await config.rotationHelper.purgeDeletedSecret(testSecretName);
    console.log();

    // Step 8: Cache statistics
    console.log('STEP 8: Cache Statistics');
    console.log('-'.repeat(80));

    const stats = config.cachingProvider.getCacheStats();
    console.log(`Cache size: ${stats.size} secret(s)`);
    console.log('Cached secrets:');
    stats.secrets.forEach((s) => {
      console.log(`  - ${s.name} (cached at: ${s.cachedAt})`);
    });
    console.log();

    console.log('='.repeat(80));
    console.log('Demo completed successfully!');
    console.log('='.repeat(80));
  } catch (error: any) {
    console.error('\n❌ Error during demo:');
    console.error(error.message);

    if (error.message.includes('AZURE_KEY_VAULT_URL')) {
      console.error('\nℹ️  To run this demo:');
      console.error('   1. Set the AZURE_KEY_VAULT_URL environment variable');
      console.error('   2. Ensure your Azure credentials are configured');
      console.error('   3. Run in an Azure environment with managed identity enabled');
    }

    process.exit(1);
  }
}

function maskValue(value: string): string {
  if (value.length <= 8) {
    return '*'.repeat(value.length);
  }
  return value.substring(0, 4) + '*'.repeat(value.length - 8) + value.substring(value.length - 4);
